  "merchant_attachments": [
    {
      "type": "uploaded document",
      "title": "Label delta is not accessory-mass corroboration",
      "text": "declared_weight 0.39 kg is a shipping-label field (merchant-supplied estimate). scanned_weight 0.32 kg is the carrier’s actual mass of the sealed parcel. Over-declaration is routine. Soft carrying-case mass ≈ 18–22 g. Removing that item cannot produce a 70 g declared-vs-scanned gap. Under the rulebook weight-consistency check the delta is therefore non-corroborative of the claimed missing accessory and supplies no Step-1 proof of absence."
    },
    {
      "type": "uploaded document",
      "title": "Caption is not visual proof of absence",
      "text": "Delivery evidence lists a buyer upload whose only content is a textual description restating the claim. No image bytes, no perceptual hash, no C2PA, no GPS. Metadata: device “phone”, taken_at ending :00 after POD and sole custody. Rulebook expressly treats buyer photos as manipulable and requires metadata checks. A post-custody caption asserting absence cannot outweigh the pre-custody sealed scan, packing record, serial registry, and signed POD."
    }
  ],
  "merchant_packing_record": {
    "packed_items": [
      {
        "title": "Apple AirPods Pro 3",
        "serial": "SN95FA182F56",
        "condition": "New",
        "colour": "Black",
        "accessories": ["USB-C charging cable", "carrying case"]
